create extension if not exists pgcrypto;

create table public.users (id uuid primary key references auth.users(id) on delete cascade, name text not null check (char_length(name) between 2 and 80), phone text not null check (char_length(phone) between 6 and 30), avatar text, created_at timestamptz not null default now());
create table public.posts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, text text not null default '' check (char_length(text) <= 5000), image_url text, video_url text, likes integer not null default 0 check (likes >= 0), created_at timestamptz not null default now(), check (image_url is not null or video_url is not null or char_length(trim(text)) > 0));
create table public.products (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, title text not null check (char_length(title) between 2 and 140), price numeric(12,2) not null check (price >= 0), image_url text, whatsapp text not null check (char_length(whatsapp) between 6 and 30), created_at timestamptz not null default now());
create table public.ads (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id) on delete cascade, post_id uuid not null references public.posts(id) on delete cascade, payment_proof text, status text not null default 'pending_review' check (status in ('pending_review','approved','rejected','expired')), created_at timestamptz not null default now(), starts_at timestamptz, ends_at timestamptz, check ((status <> 'approved') or (starts_at is not null and ends_at is not null)));
create table public.comments (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.users(id) on delete cascade, text text not null check (char_length(trim(text)) between 1 and 1000), created_at timestamptz not null default now());
create table public.post_reactions (post_id uuid not null references public.posts(id) on delete cascade, user_id uuid not null references public.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (post_id,user_id));
create table public.conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now());
create table public.conversation_members (conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references public.users(id) on delete cascade, created_at timestamptz not null default now(), primary key (conversation_id,user_id));
create table public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references public.users(id) on delete cascade, body text not null default '' check (char_length(body) <= 3000), media_url text, created_at timestamptz not null default now(), check (char_length(trim(body)) > 0 or media_url is not null));
create index posts_created_at_idx on public.posts(created_at desc); create index products_created_at_idx on public.products(created_at desc); create index comments_post_id_idx on public.comments(post_id, created_at); create index messages_conversation_id_idx on public.messages(conversation_id, created_at); create unique index active_ad_per_post_idx on public.ads(post_id) where status in ('pending_review','approved');

alter table public.users enable row level security; alter table public.posts enable row level security; alter table public.products enable row level security; alter table public.ads enable row level security; alter table public.comments enable row level security; alter table public.post_reactions enable row level security; alter table public.conversations enable row level security; alter table public.conversation_members enable row level security; alter table public.messages enable row level security;

create policy users_read_own on public.users for select to authenticated using (id=auth.uid()); create policy users_insert_own on public.users for insert to authenticated with check (id=auth.uid()); create policy users_update_own on public.users for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy posts_read_public on public.posts for select using (true); create policy posts_insert_own on public.posts for insert to authenticated with check (user_id=auth.uid()); create policy posts_update_own on public.posts for update to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy posts_delete_own on public.posts for delete to authenticated using (user_id=auth.uid());
create policy products_read_public on public.products for select using (true); create policy products_insert_own on public.products for insert to authenticated with check (user_id=auth.uid()); create policy products_update_own on public.products for update to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy products_delete_own on public.products for delete to authenticated using (user_id=auth.uid());
create policy ads_read_approved_or_own on public.ads for select to authenticated using (user_id=auth.uid() or status='approved'); create policy ads_insert_own on public.ads for insert to authenticated with check (user_id=auth.uid());
create policy comments_read_public on public.comments for select using (true); create policy comments_insert_own on public.comments for insert to authenticated with check (user_id=auth.uid()); create policy comments_update_own on public.comments for update to authenticated using (user_id=auth.uid()) with check (user_id=auth.uid()); create policy comments_delete_own on public.comments for delete to authenticated using (user_id=auth.uid());
create policy reactions_read_public on public.post_reactions for select using (true); create policy reactions_insert_own on public.post_reactions for insert to authenticated with check (user_id=auth.uid()); create policy reactions_delete_own on public.post_reactions for delete to authenticated using (user_id=auth.uid());
create policy conversations_read_members on public.conversations for select to authenticated using (exists (select 1 from public.conversation_members cm where cm.conversation_id=conversations.id and cm.user_id=auth.uid())); create policy memberships_read_own on public.conversation_members for select to authenticated using (user_id=auth.uid()); create policy messages_read_members on public.messages for select to authenticated using (exists (select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid())); create policy messages_send_members on public.messages for insert to authenticated with check (sender_id=auth.uid() and exists (select 1 from public.conversation_members cm where cm.conversation_id=messages.conversation_id and cm.user_id=auth.uid()));

create or replace function public.start_direct_conversation(other_user uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare current_user_id uuid:=auth.uid(); existing_conversation uuid; new_conversation uuid; begin if current_user_id is null then raise exception 'Not authenticated'; end if; if current_user_id=other_user then raise exception 'A direct conversation requires another user'; end if; if not exists (select 1 from public.users where id=other_user) then raise exception 'User not found'; end if; select cm1.conversation_id into existing_conversation from public.conversation_members cm1 join public.conversation_members cm2 on cm2.conversation_id=cm1.conversation_id where cm1.user_id=current_user_id and cm2.user_id=other_user group by cm1.conversation_id having count(*)=2 limit 1; if existing_conversation is not null then return existing_conversation; end if; insert into public.conversations default values returning id into new_conversation; insert into public.conversation_members(conversation_id,user_id) values(new_conversation,current_user_id),(new_conversation,other_user); return new_conversation; end; $$; grant execute on function public.start_direct_conversation(uuid) to authenticated;

create or replace view public.public_profiles with (security_invoker=false) as select id,name,avatar,created_at from public.users; grant select on public.public_profiles to anon,authenticated;
alter publication supabase_realtime add table public.posts, public.comments, public.post_reactions, public.messages, public.products, public.ads;
